// Written pre-game note: facts builder, prompt, and checker.

import type { GamePlan, Role } from './types.ts'
import type { SeriesOutlook, OutlookPlayer } from './outlook.ts'

// ── Types ────────────────────────────────────────────────────────────

/** A written note generated by the language model. */
export interface WrittenNote {
  headline: string
  points: { title: string; text: string }[]
}

/** One player's facts for the note. */
export interface NotePlayerFacts {
  player: string
  role: string | null
  usualPicksAlreadyGonePct: number
  limitedHistory?: true
  usualPicksAlreadyGone: string[]
  likelyPicksNow: { champion: string; likelihoodPct: number; gamesPlayed: number }[]
}

/** One ban-to-consider fact. */
export interface NoteBanFacts {
  champion: string
  chanceOpponentPicksItPct: number
  chanceWePickItPct: number
  opponentPlayer: string
}

/** One denial-pick fact. */
export interface NoteDenialFacts {
  champion: string
  ownPlayer: string
  ownLikelihoodPct: number
  chanceOpponentPicksItPct: number
}

/** The full facts object sent to the model. */
export interface NoteFacts {
  team: string
  opponent: string
  game: number
  score: string
  championsGoneForBothTeams: string[]
  ownPlayers: NotePlayerFacts[]
  opponentPlayers: NotePlayerFacts[]
  bansToConsider: NoteBanFacts[]
  picksThatAlsoDeny: NoteDenialFacts[]
}

/** A problem found during note checking. */
export interface NoteProblem {
  rule: string
  detail: string
}

// ── Prompt ───────────────────────────────────────────────────────────

export const NOTE_PROMPT_VERSION = 1

export const NOTE_PROMPT = `You write a short pre-game note for the coach of one League of Legends team in a Fearless Draft series (a champion picked by either team in an earlier game is gone for both teams for the rest of the series).
You get facts as JSON, computed by a planning board. "We" is the team in "team".
What the coach needs is the two or three things that stand out, not a list of every player:
- "Their pools": the opponent player who has lost the most of their usual picks (name what is gone and what they are most likely to pick now), and the one who has lost the least.
- "Our pools": the same for our team, in the same order.
- "Bans and picks": the one or two bans from "bansToConsider" with the largest gap between the two chances, and one pick from "picksThatAlsoDeny", saying which opponent it takes a pick from.
Rules:
- Use only names and numbers that appear in the facts. Never add a champion, a player, a number or a fact from your own knowledge of the game.
- Never write a field name from the JSON. Say it in words: "has lost 51% of his usual picks", "a 25% chance".
- At most two players per point and at most five percentages in the whole note.
- Do not predict who wins, and do not say that a team is favoured, ahead, or at an advantage or disadvantage. The score may be stated.
- Do not give reasons from game knowledge (matchups, synergy, meta strength).
- Do not use "he", "his", "she" or "her" for a player; repeat the name or use "they".
- Plain English, short sentences, no hype. If a list in the facts is empty, say so in a few words.
Return JSON: { "headline": one sentence of at most 14 words naming the single most notable fact, "points": exactly three objects { "title", "text" } with titles "Their pools", "Our pools", "Bans and picks", each text at most 40 words }.
`

// ── Names helper ─────────────────────────────────────────────────────

/** Maps from ID to name for champions, players, and teams. */
export interface NoteNames {
  champion: (id: string) => string
  player: (id: string) => string
  team: (id: string) => string
}

// ── 1.1: noteFacts ───────────────────────────────────────────────────

/**
 * Build the facts object for one team before one game.
 * Percentages are whole numbers (0-100).
 */
export function noteFacts(
  plan: GamePlan,
  outlook: SeriesOutlook,
  names: NoteNames,
  teamId: string,
  /** Games won so far in the series by this team and by the opponent. */
  wins: { own: number; opponent: number },
): NoteFacts {
  const oppTeamId = plan.game.sides.blue === teamId ? plan.game.sides.red : plan.game.sides.blue
  const gameNumber = plan.game.gameNumber

  // Score string
  const score = buildScore(plan, names, teamId, wins)

  // Champions burned (names)
  const championsGone = Array.from(plan.burned).map(id => names.champion(id))

  // Own and opponent players
  const ownPlayers = buildPlayerFacts(plan, outlook, names, teamId)
  const opponentPlayers = buildPlayerFacts(plan, outlook, names, oppTeamId)

  // Bans to consider: top 3 from leverage where gap > 2 points
  const leverage = plan.leverage.get(teamId)
  const bansToConsider: NoteBanFacts[] = []
  if (leverage) {
    for (const entry of leverage.leverage) {
      const gap = Math.round(entry.threatFromOpponent * 100) - Math.round(entry.threatFromOwn * 100)
      if (gap <= 2) continue
      const oppPlayer = entry.opponentHits.length > 0
        ? names.player(entry.opponentHits[0].playerId)
        : ''
      bansToConsider.push({
        champion: names.champion(entry.championId),
        chanceOpponentPicksItPct: Math.round(entry.threatFromOpponent * 100),
        chanceWePickItPct: Math.round(entry.threatFromOwn * 100),
        opponentPlayer: oppPlayer,
      })
      if (bansToConsider.length >= 3) break
    }
  }

  // Picks that also deny: top 3
  const picksThatAlsoDeny: NoteDenialFacts[] = []
  if (leverage) {
    for (const entry of leverage.denial) {
      picksThatAlsoDeny.push({
        champion: names.champion(entry.championId),
        ownPlayer: entry.ownPlayerName,
        ownLikelihoodPct: Math.round(entry.ownProbability * 100),
        chanceOpponentPicksItPct: Math.round(entry.threatFromOpponent * 100),
      })
      if (picksThatAlsoDeny.length >= 3) break
    }
  }

  return {
    team: names.team(teamId),
    opponent: names.team(oppTeamId),
    game: gameNumber,
    score,
    championsGoneForBothTeams: championsGone,
    ownPlayers,
    opponentPlayers,
    bansToConsider,
    picksThatAlsoDeny,
  }
}

/** Build score string like "G2 Esports 0 - 2 Movistar KOI". */
function buildScore(plan: GamePlan, names: NoteNames, teamId: string, wins: { own: number; opponent: number }): string {
  const oppTeamId = plan.game.sides.blue === teamId ? plan.game.sides.red : plan.game.sides.blue
  const teamName = names.team(teamId)
  const oppName = names.team(oppTeamId)
  return `${teamName} ${wins.own} - ${wins.opponent} ${oppName}`
}

/**
 * Whether the facts carry enough to write about: at least eight of the ten players have 20 or more
 * earlier games, and every player has a list of likely picks. Early series in the data fail this.
 */
export function noteWorthwhile(facts: NoteFacts): boolean {
  const all = [...facts.ownPlayers, ...facts.opponentPlayers]
  if (all.length < 10) return false
  if (all.some(p => p.likelyPicksNow.length === 0)) return false
  return all.filter(p => !p.limitedHistory).length >= 8
}

/** Build player facts for one team. */
function buildPlayerFacts(
  plan: GamePlan,
  outlook: SeriesOutlook,
  names: NoteNames,
  teamId: string,
): NotePlayerFacts[] {
  const roleOrder: Role[] = ['top', 'jungle', 'mid', 'bot', 'support']
  const result: NotePlayerFacts[] = []

  const roleMap = plan.players.find(([tid]) => tid === teamId)?.[1]
  if (!roleMap) return result

  const outlookTeam = outlook.teams.find((t: { teamId: string }) => t.teamId === teamId)

  for (const role of roleOrder) {
    const gp = roleMap.get(role)
    if (!gp) continue

    const outlookPlayer = outlookTeam?.players.find((p: OutlookPlayer) => p.playerId === gp.playerId)
    const burnedShare = outlookPlayer?.burnedShare ?? 0

    // Up to 3 burned champions highest in startLikelihoods
    const usualPicksAlreadyGone: string[] = []
    for (const l of gp.startLikelihoods) {
      if (plan.burned.has(l.championId)) {
        usualPicksAlreadyGone.push(names.champion(l.championId))
        if (usualPicksAlreadyGone.length >= 3) break
      }
    }

    // Up to 3 likely picks now (from current likelihoods)
    const likelyPicksNow: { champion: string; likelihoodPct: number; gamesPlayed: number }[] = []
    for (const l of gp.likelihoods) {
      const poolEntry = gp.pool.credible.find((pe: { championId: string; games: number }) => pe.championId === l.championId)
      likelyPicksNow.push({
        champion: names.champion(l.championId),
        likelihoodPct: Math.round(l.probability * 100),
        gamesPlayed: poolEntry?.games ?? 0,
      })
      if (likelyPicksNow.length >= 3) break
    }

    const pf: NotePlayerFacts = {
      player: gp.playerName,
      role: gp.role,
      usualPicksAlreadyGonePct: Math.round(burnedShare * 100),
      usualPicksAlreadyGone,
      likelyPicksNow,
    }
    if (gp.priorGames < 20) {
      pf.limitedHistory = true
    }
    result.push(pf)
  }

  // Unknown role players
  const unknownList = plan.unknownRolePlayers.find(([tid]) => tid === teamId)?.[1] ?? []
  for (const gp of unknownList) {
    const outlookPlayer = outlookTeam?.players.find((p: OutlookPlayer) => p.playerId === gp.playerId)
    const burnedShare = outlookPlayer?.burnedShare ?? 0

    const usualPicksAlreadyGone: string[] = []
    for (const l of gp.startLikelihoods) {
      if (plan.burned.has(l.championId)) {
        usualPicksAlreadyGone.push(names.champion(l.championId))
        if (usualPicksAlreadyGone.length >= 3) break
      }
    }

    const likelyPicksNow: { champion: string; likelihoodPct: number; gamesPlayed: number }[] = []
    for (const l of gp.likelihoods) {
      const poolEntry = gp.pool.credible.find((pe: { championId: string; games: number }) => pe.championId === l.championId)
      likelyPicksNow.push({
        champion: names.champion(l.championId),
        likelihoodPct: Math.round(l.probability * 100),
        gamesPlayed: poolEntry?.games ?? 0,
      })
      if (likelyPicksNow.length >= 3) break
    }

    const pf: NotePlayerFacts = {
      player: gp.playerName,
      role: null,
      usualPicksAlreadyGonePct: Math.round(burnedShare * 100),
      usualPicksAlreadyGone,
      likelyPicksNow,
    }
    if (gp.priorGames < 20) {
      pf.limitedHistory = true
    }
    result.push(pf)
  }

  return result
}

// ── 1.3: checkNote ──────────────────────────────────────────────────

/**
 * Check a generated note against the facts. Returns a list of problems
 * (empty means it passes).
 */
export function checkNote(
  facts: NoteFacts,
  note: WrittenNote,
  championNames: string[],
): NoteProblem[] {
  const problems: NoteProblem[] = []

  // Combine all text for analysis
  const allText = note.headline + ' ' + note.points.map(p => p.title + ' ' + p.text).join(' ')

  // 1. Champion name in note but not in facts
  for (const champName of championNames) {
    if (allText.includes(champName)) {
      // Check if this champion is in the facts
      const inFacts = championInFacts(facts, champName)
      if (!inFacts) {
        problems.push({ rule: 'unknown_champion', detail: `Champion "${champName}" is in the note but not in the facts` })
      }
    }
  }

  // 2. Percentage in note whose number is not a value in the facts
  const percentagesInNote = allText.match(/\d+%/g) ?? []
  const percentagesInFacts = getAllPercentages(facts)
  for (const pctStr of percentagesInNote) {
    const num = parseInt(pctStr, 10)
    if (!percentagesInFacts.has(num)) {
      problems.push({ rule: 'unknown_percentage', detail: `Percentage "${pctStr}" is in the note but not in the facts` })
    }
  }

  // 3. More than six percentages
  if (percentagesInNote.length > 6) {
    problems.push({ rule: 'too_many_percentages', detail: `Note has ${percentagesInNote.length} percentages (max 6)` })
  }

  // 4. More than 150 words
  const words = allText.split(/\s+/).filter(w => w.length > 0)
  if (words.length > 150) {
    problems.push({ rule: 'too_many_words', detail: `Note has ${words.length} words (max 150)` })
  }

  // 5. Not exactly three points with the three titles
  if (note.points.length !== 3) {
    problems.push({ rule: 'wrong_number_of_points', detail: `Note has ${note.points.length} points (expected 3)` })
  } else {
    const expectedTitles = ['Their pools', 'Our pools', 'Bans and picks']
    const actualTitles = note.points.map(p => p.title)
    for (const expected of expectedTitles) {
      if (!actualTitles.includes(expected)) {
        problems.push({ rule: 'missing_title', detail: `Note is missing the title "${expected}"` })
      }
    }
  }

  // 6. Forbidden words
  const forbiddenWords = ['favour', 'favor', 'advantage', 'ahead', 'will win', 'will lose', 'likely to win']
  const lowerText = allText.toLowerCase()
  for (const word of forbiddenWords) {
    if (lowerText.includes(word)) {
      problems.push({ rule: 'forbidden_word', detail: `Note contains "${word}"` })
    }
  }

  // 7. Field name from facts
  const fieldNames = ['Pct', 'usualPicks', 'likelyPicksNow', 'usualPicksAlreadyGone', 'limitedHistory',
    'chanceOpponentPicksItPct', 'chanceWePickItPct', 'ownLikelihoodPct', 'likelihoodPct', 'gamesPlayed',
    'championsGoneForBothTeams', 'ownPlayers', 'opponentPlayers', 'bansToConsider', 'picksThatAlsoDeny']
  for (const fieldName of fieldNames) {
    if (allText.includes(fieldName)) {
      problems.push({ rule: 'field_name', detail: `Note contains field name "${fieldName}"` })
    }
  }

  // 8. Pronouns as whole words
  const pronouns = ['he', 'his', 'she', 'her']
  for (const pronoun of pronouns) {
    const regex = new RegExp(`\\b${pronoun}\\b`, 'i')
    if (regex.test(allText)) {
      problems.push({ rule: 'pronoun', detail: `Note contains pronoun "${pronoun}"` })
    }
  }

  return problems
}

/** Check if a champion name appears anywhere in the facts. */
function championInFacts(facts: NoteFacts, champName: string): boolean {
  if (facts.championsGoneForBothTeams.includes(champName)) return true
  for (const p of facts.ownPlayers) {
    if (p.usualPicksAlreadyGone.includes(champName)) return true
    for (const lp of p.likelyPicksNow) {
      if (lp.champion === champName) return true
    }
  }
  for (const p of facts.opponentPlayers) {
    if (p.usualPicksAlreadyGone.includes(champName)) return true
    for (const lp of p.likelyPicksNow) {
      if (lp.champion === champName) return true
    }
  }
  for (const b of facts.bansToConsider) {
    if (b.champion === champName) return true
  }
  for (const d of facts.picksThatAlsoDeny) {
    if (d.champion === champName) return true
  }
  return false
}

/** Collect all percentage values from the facts. */
function getAllPercentages(facts: NoteFacts): Set<number> {
  const set = new Set<number>()
  for (const p of facts.ownPlayers) {
    set.add(p.usualPicksAlreadyGonePct)
    for (const lp of p.likelyPicksNow) {
      set.add(lp.likelihoodPct)
    }
  }
  for (const p of facts.opponentPlayers) {
    set.add(p.usualPicksAlreadyGonePct)
    for (const lp of p.likelyPicksNow) {
      set.add(lp.likelihoodPct)
    }
  }
  for (const b of facts.bansToConsider) {
    set.add(b.chanceOpponentPicksItPct)
    set.add(b.chanceWePickItPct)
  }
  for (const d of facts.picksThatAlsoDeny) {
    set.add(d.ownLikelihoodPct)
    set.add(d.chanceOpponentPicksItPct)
  }
  return set
}
